    &self,
    versioned_hashes: Vec<Hash256>,
) -> Result<Vec<Option<BlobAndProofV1<E>>>, Error> {
    let params = json!([versioned_hashes]);

    self.rpc_request(
        ENGINE_GET_BLOBS_V1,
        params,
